"use client";
import Link from "next/link";
import { useState } from "react";
import { useParams } from "next/navigation";
import { BookOpen, Users, GraduationCap, UserRound, Download, Search, ShieldCheck } from "lucide-react";
import { useLearnova } from "@/components/LearnovaProvider";
import { DashboardCard, EmptyState, LoadingCards, PageHeader, ProgressBar, StatusBadge } from "@/components/ui";
import { categories } from "@/data/courses";
import { emptyLearning, formatDate, progressFor } from "@/lib/learnova-state";
import { downloadText } from "@/lib/download";

export default function AdminViews({ view = "overview" }: { view?: "overview" | "users" | "students" | "instructors" | "reports" | "settings" | "enrollments" }) {
  const { state, user, dispatch } = useLearnova();
  const [search, setSearch] = useState(""); const [role, setRole] = useState("All"); const [message, setMessage] = useState("");
  const students = state.users.filter(u => u.role === "student"); const instructors = state.users.filter(u => u.role === "instructor");
  const enrollments = Object.values(state.learning).reduce((sum, l) => sum + Object.keys(l.enrollments).length, 0);
  const visibleUsers = state.users.filter(u => (view !== "students" || u.role === "student") && (view !== "instructors" || u.role === "instructor") && (role === "All" || u.role === role) && `${u.name} ${u.email}`.toLowerCase().includes(search.toLowerCase()));
  if (!state.ready) return <LoadingCards />;
  async function deleteUser(id: string) {
    if (state.courses.some(c => c.instructorId === id)) { setMessage("This instructor owns courses. Remove or reassign those courses before deleting the account."); return; }
    if (window.confirm("Delete this account and its learning records?")) { if (!(await dispatch({ type: "delete-user", id })).ok) return; setMessage("Account removed."); }
  }
  const userTable = (recent = false) => <div className="table-wrap"><table className="data-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Joined Date</th><th>Actions</th></tr></thead><tbody>{(recent ? state.users.slice(-5).reverse() : visibleUsers).map(u => <tr key={u.id}><td className="font-semibold">{u.name}</td><td>{u.email}</td><td className="capitalize">{u.role}</td><td><StatusBadge tone={u.status === "Active" ? "green" : "red"}>{u.status}</StatusBadge></td><td className="whitespace-nowrap">{formatDate(u.joined)}</td><td><div className="flex gap-3 whitespace-nowrap"><Link className="font-semibold text-blue-400" href={`/admin-dashboard/users/${u.id}`}>View</Link><button className="font-semibold text-amber-300 disabled:opacity-40" disabled={u.id === user?.id || u.role === "admin"} title={u.role === "admin" ? "Administrator accounts are protected" : undefined} onClick={() => dispatch({ type: "user-status", id: u.id })}>{u.status === "Blocked" ? "Unblock" : "Block"}</button><button className="font-semibold text-red-500 disabled:opacity-40" disabled={u.id === user?.id || u.role === "admin"} onClick={() => deleteUser(u.id)}>Delete</button></div></td></tr>)}</tbody></table>{!recent && !visibleUsers.length && <p className="p-7 text-center text-sm text-slate-400">No matching accounts. Try another search.</p>}</div>;
  if (["users", "students", "instructors"].includes(view)) return <><PageHeader title={view === "users" ? "User Management" : view === "students" ? "Students" : "Instructors"} description="Review accounts and manage access to Learnova." /><div className="panel mb-6 flex flex-wrap gap-4 p-4"><label className="flex min-w-0 flex-1 items-center gap-3"><Search size={18} className="shrink-0 text-slate-400" /><span className="sr-only">Search users</span><input className="field" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name or email..." /></label>{view === "users" && <label className="min-w-40"><span className="sr-only">Filter by role</span><select className="field" value={role} onChange={e => setRole(e.target.value)}><option value="All">All roles</option><option value="student">Student</option><option value="instructor">Instructor</option><option value="admin">Admin</option></select></label>}</div>{message && <p className="notice mb-5" role="status">{message}</p>}{userTable()}</>;
  if (view === "enrollments") return <><PageHeader title="Course Enrollments" description="Review student enrollments and course progress across the platform." />{enrollments ? <div className="table-wrap"><table className="data-table"><thead><tr><th>Student</th><th>Course</th><th>Progress</th><th>Status</th></tr></thead><tbody>{students.flatMap(student=>state.courses.filter(course=>state.learning[student.id]?.enrollments[course.id]).map(course=>{const progress=progressFor(course,state.learning[student.id]);return <tr key={student.id+'-'+course.id}><td><Link className="text-violet-300" href={'/admin-dashboard/users/'+student.id}>{student.name}</Link></td><td><Link href={'/courses/'+course.id}>{course.title}</Link></td><td className="min-w-44"><ProgressBar value={progress}/></td><td><StatusBadge tone={progress===100?'green':'blue'}>{progress===100?'Completed':'In progress'}</StatusBadge></td></tr>;}))}</tbody></table></div>:<EmptyState description="Student enrollments will appear here as learners join courses."/>}</>;
  if (view === "settings") return <><PageHeader art="settingsIcon" title="Settings" description="Manage preferences for Learnova." /><section className="panel max-w-2xl space-y-6 p-6"><h2 className="section-title">Communication preferences</h2><label className="flex items-center gap-3"><input type="checkbox" checked={state.settings.notifications} onChange={async e => { if (!(await dispatch({ type: "settings", settings: { ...state.settings, notifications: e.target.checked } })).ok) return; setMessage("Preferences saved."); }} /><span className="text-sm">Learning notifications</span></label><label className="flex items-center gap-3"><input type="checkbox" checked={state.settings.weeklyDigest} onChange={async e => { if (!(await dispatch({ type: "settings", settings: { ...state.settings, weeklyDigest: e.target.checked } })).ok) return; setMessage("Preferences saved."); }} /><span className="text-sm">Weekly learning digest</span></label><p className="text-xs leading-6 text-slate-400">Preferences are saved to the platform. Scheduled notifications and digests are not configured.</p>{message && <p className="notice" role="status">{message}</p>}</section><section className="panel mt-6 max-w-2xl p-6"><h2 className="section-title">Demo data</h2><p className="mt-3 text-sm leading-7 text-slate-400">Restore missing sample accounts and courses in development. Existing records are preserved.</p><button className="btn-secondary mt-5" onClick={async () => { if (window.confirm("Restore missing sample accounts and courses? Existing records will be preserved.")) { if ((await dispatch({ type: "reset" })).ok) setMessage("Missing sample records restored."); } }}>Restore Sample Data</button></section></>;
  if (view === "reports") {
    const completed = state.courses.reduce((sum, c) => sum + Object.values(state.learning).filter(l => progressFor(c, l) === 100).length, 0);
    const attempts = Object.values(state.learning).flatMap(l => Object.values(l.quizzes)); const average = attempts.length ? Math.round(attempts.reduce((sum, q) => sum + q.score, 0) / attempts.length) : 0;
    return <><PageHeader title="Reports" description="A clear view of platform learning activity." action={<button className="btn-primary" onClick={() => { const rows = [["Metric", "Value"], ["Students", students.length], ["Instructors", instructors.length], ["Courses", state.courses.length], ["Enrollments", enrollments], ["Completed courses", completed], ["Average quiz score", average]]; downloadText("learnova-report.csv", rows.map(row => row.join(",")).join("\n"), "text/csv"); }}><Download size={17} />Export Report</button>} /><div className="mb-7 grid gap-4 sm:grid-cols-3"><DashboardCard label="Total Enrollments" value={enrollments} icon={BookOpen} /><DashboardCard label="Course Completions" value={completed} icon={GraduationCap} /><DashboardCard label="Average Quiz Score" value={`${average}%`} icon={ShieldCheck} /></div><div className="panel p-6"><h2 className="section-title">Courses by Category</h2><div className="mt-6 space-y-6">{categories.map(category => { const count = state.courses.filter(c => c.category === category).length; return <ProgressBar key={category} value={state.courses.length ? Math.round(count / state.courses.length * 100) : 0} label={`${category} · ${count} courses`} />; })}</div></div></>;
  }
  return <><PageHeader art="admin" title="Admin Dashboard" eyebrow="Learnova at a glance" description="Support your learning community and keep the platform organized." /><div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><DashboardCard label="Total Students" value={students.length} icon={GraduationCap} /><DashboardCard label="Total Instructors" value={instructors.length} icon={UserRound} /><DashboardCard label="Total Courses" value={state.courses.length} icon={BookOpen} /><DashboardCard label="Total Enrollments" value={enrollments} icon={Users} /></div><h2 className="section-title mb-5">Recent Users</h2>{userTable(true)}<div className="mt-8 grid gap-6 xl:grid-cols-2"><section className="panel p-6"><div className="flex justify-between gap-3"><h2 className="section-title">Courses</h2><Link className="text-sm font-semibold text-blue-400" href="/admin-dashboard/courses">Manage</Link></div><div className="mt-4 space-y-4">{state.courses.slice(0, 5).map(c => <Link key={c.id} href={`/courses/${c.id}`} className="flex items-center justify-between gap-3 rounded-xl bg-blue-500/5 p-4"><div><p className="text-sm font-semibold">{c.title}</p><p className="mt-1 text-xs text-slate-400">{c.instructor}</p></div><StatusBadge>{c.category}</StatusBadge></Link>)}</div></section><section className="panel p-6"><h2 className="section-title">System Activity</h2>{state.activity.slice(0, 6).map((item, i) => <div key={i} className="mt-5 flex gap-3 text-sm leading-6 text-slate-400"><span className="mt-2 h-2 w-2 shrink-0 rounded-full bg-blue-500" />{item}</div>)}</section></div></>;
}
export function UserDetail() {
  const { id } = useParams<{ id: string }>(); const { state } = useLearnova(); const user = state.users.find(u => u.id === id);
  if (!state.ready) return <LoadingCards />;
  if (!user) return <EmptyState title="Account not found" description="This account may have been removed." href="/admin-dashboard/users" action="View Users" />;
  const learning = state.learning[id] ?? emptyLearning();
  return <><PageHeader title={user.name} description={user.email} action={<Link className="btn-secondary" href="/admin-dashboard/users">Back to Users</Link>} /><div className="panel p-6"><div className="flex gap-3"><StatusBadge>{user.role}</StatusBadge><StatusBadge tone={user.status === "Active" ? "green" : "red"}>{user.status}</StatusBadge></div><dl className="mt-6 grid gap-5 sm:grid-cols-2">{[["Joined", formatDate(user.joined)], ["Phone", user.phone || "Not provided"], ["Bio", user.bio || "No bio added"]].map(([label, value]) => <div key={label}><dt className="text-sm text-slate-400">{label}</dt><dd className="mt-2 text-sm font-semibold">{value}</dd></div>)}</dl></div><div className="panel mt-6 p-6"><h2 className="section-title">Learning Activity</h2>{state.courses.filter(c => learning.enrollments[c.id]).map(c => <div className="mt-5" key={c.id}><ProgressBar value={progressFor(c, learning)} label={c.title} /></div>)}{!Object.keys(learning.enrollments).length && <p className="mt-4 text-sm text-slate-400">No course enrollments recorded.</p>}</div></>;
}
